from collections import defaultdict
shape_to_comp_list = defaultdict(list)

for color in [6, 7, 0, 4]:
    visited = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r, c) not in visited:
                comp_cells = []
                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) in visited: continue
                    visited.add((curr_r, curr_c))
                    comp_cells.append((curr_r, curr_c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))
                min_r = min(x for x,y in comp_cells)
                min_c = min(y for x,y in comp_cells)
                shape_key = tuple(sorted(((x-min_r, y-min_c) for x,y in comp_cells)))
                key = (len(comp_cells), tuple(shape_key))
                shape_to_comp_list[key].append({'color': color, 'cells': comp_cells})

dup_keys = [k for k, v in shape_to_comp_list.items() if len(v) > 1]
unique_keys = [k for k, v in shape_to_comp_list.items() if len(v) == 1]

output_grid = [[3 for _ in range(23)] for _ in range(20)]

# For dups: keep ALL cells from both items but use first's color
for key in dup_keys:
    comps = sorted(shape_to_comp_list[key], key=lambda c: min(c['cells']))
    first_color = comps[0]['color']
    # Union all cells from both components
    all_cells = list(set(comps[0]['cells']) | set(comps[1]['cells']))
    for r, c in all_cells:
        output_grid[r][c] = first_color

# Keep unique shapes unchanged
for key in unique_keys:
    for item in shape_to_comp_list[key]:
        for r, c in item['cells']:
            output_grid[r][c] = item['color']

import json
print(json.dumps({"action": "submit", "grid": output_grid}))

